/**
 * Regenerate `docs/screenshots/` by driving the real client.
 *
 * These were produced ad hoc twice -- October and November 2026 -- and both
 * times the two traps below had to be rediscovered from the note in
 * CLAUDE.md. A screenshot set that is regenerated by hand is one nobody
 * regenerates, which is how `docs/screenshots/` came to be showing an app
 * three palettes out of date on the project's most shareable surface.
 *
 * Nothing here is mocked. The client talks to a real server, and the stub
 * backend is why the species names are meaningless -- the refusal logic
 * around them is not. Do not add a route interception to make a prettier
 * verdict: the point of these images is that the app really did that.
 *
 *   python scripts/try_it.py              # or uvicorn + expo by hand
 *   node scripts/screenshots.js
 *
 * TWO TRAPS, both invisible until the output is wrong.
 *
 * 1. react-navigation keeps earlier screens MOUNTED but hidden, so a text
 *    selector happily resolves to a twin on a screen you left two steps
 *    ago. Everything here filters on isVisible().
 *
 * 2. `fullPage: true` stops at the viewport, because React Native Web
 *    scrolls an inner container rather than the document -- so the page
 *    "is" one screen tall however long the content is. Rather than trim
 *    afterwards, `fit()` measures the tallest scrolling container and
 *    resizes the viewport to it, so the capture is the whole screen and
 *    needs no cropping.
 */
const { chromium } = require('playwright');
const { resolve } = require('node:path');

const ROOT = resolve(__dirname, '..');
const OUT = resolve(ROOT, 'docs', 'screenshots');
const URL = process.env.APP_URL || 'http://localhost:8081';
// A real photograph, committed, so the set does not depend on anything
// outside the repository. It is the masthead's frame: a mushroom in moss.
const PHOTO = resolve(ROOT, 'docs', 'design', 'masthead-source.jpg');

const WIDTH = 390;          // iPhone-class logical width; x2 => 780px assets
// A real phone's height, so a screen with little on it reads as a phone
// screen with space at the bottom rather than as a crop. Anything taller
// than this grows; nothing shrinks below it.
const HEIGHT = 844;
const MAX_HEIGHT = 6000;

const sleep = (p, ms) => p.waitForTimeout(ms);

/** The visible one. See trap 1. */
async function tap(p, re, { timeout = 6000 } = {}) {
  const deadline = Date.now() + timeout;
  while (Date.now() < deadline) {
    for (const l of await p.locator('[role="button"], [role="checkbox"], [role="tab"], [role="link"]').all()) {
      if (!(await l.isVisible().catch(() => false))) continue;
      const t = ((await l.innerText().catch(() => '')) || '').replace(/\s+/g, ' ').trim();
      if (re.test(t)) { await l.click().catch(() => {}); return t; }
    }
    await sleep(p, 300);
  }
  const seen = [];
  for (const l of await p.locator('[role="button"], [role="checkbox"], [role="tab"], [role="link"]').all()) {
    if (!(await l.isVisible().catch(() => false))) continue;
    const t = ((await l.innerText().catch(() => '')) || '').trim().replace(/\n/g, ' / ');
    if (t) seen.push(t.slice(0, 60));
  }
  throw new Error(
    `no visible control matching ${re}\n    on screen: ${seen.join(' | ') || '(none)'}`,
  );
}

/**
 * The tab bar's label sits after an icon glyph that `trim()` does not
 * remove, so the accessible text of the Home tab is not the string "Home"
 * -- it ends with it. An exact match silently finds nothing.
 */
const goTab = (p, name) => tap(p, new RegExp(`${name}$`));

/** Grow the viewport to the whole screen. See trap 2. */
async function fit(p) {
  const h = await p.evaluate((cap) => {
    let max = document.documentElement.scrollHeight;
    for (const d of document.querySelectorAll('div')) {
      if (d.scrollHeight > d.clientHeight + 4) max = Math.max(max, d.scrollHeight);
    }
    return Math.min(Math.ceil(max) + 16, cap);
  }, MAX_HEIGHT);
  await p.setViewportSize({ width: WIDTH, height: h });
  await sleep(p, 700);
  return h;
}

async function shot(p, name) {
  const h = await fit(p);
  await p.screenshot({ path: resolve(OUT, name) });
  console.log(`  ${name.padEnd(42)} ${WIDTH * 2}x${h * 2}`);
  await p.setViewportSize({ width: WIDTH, height: HEIGHT });
  await sleep(p, 400);
}

(async () => {
  const browser = await chromium.launch({ args: ['--no-sandbox'] });
  const p = await browser.newPage({
    viewport: { width: WIDTH, height: HEIGHT }, deviceScaleFactor: 2,
  });
  const errs = [];
  p.on('pageerror', (e) => errs.push(String(e).slice(0, 180)));
  p.on('filechooser', async (fc) => { await fc.setFiles(PHOTO).catch(() => {}); });

  console.log(`\n  driving ${URL}\n`);
  await p.goto(URL, { waitUntil: 'domcontentloaded', timeout: 180000 });
  await sleep(p, 14000);

  // ---- consent -------------------------------------------------------
  for (const c of await p.locator('[role="checkbox"]').all()) {
    if (await c.isVisible().catch(() => false)) await c.click({ timeout: 3000 }).catch(() => {});
  }
  await sleep(p, 600);
  await shot(p, '02-consent-every-box-on-its-own.png');

  await tap(p, /^I understand — continue/);
  await sleep(p, 6000);

  // The gate opens onto Observe, not Home -- the working screen, which is
  // the right default and is NOT the front page. Capturing without this
  // step files the capture screen as `03-front-page.png`, which is how the
  // first run of this script went.
  await goTab(p, 'Home');
  await sleep(p, 3000);
  await shot(p, '03-front-page.png');

  // ---- emergency, reached the way a user reaches it -------------------
  await tap(p, /Someone has eaten a wild mushroom/);
  await sleep(p, 3000);
  await shot(p, '10-emergency.png');
  // Reload rather than goBack. The emergency screen sits above the tab
  // navigator, so there is no tab bar to leave by, and `goBack()` walked
  // out of the app entirely -- the next selector found an empty page and
  // the run died there. Consent is in localStorage, so a reload lands back
  // on the working screen with the log intact.
  await p.goto(URL, { waitUntil: 'domcontentloaded', timeout: 120000 });
  await sleep(p, 12000);

  // ---- capture: a photo, then the field notes -------------------------
  await goTab(p, 'Observe');
  await sleep(p, 3000);
  await tap(p, /The cap, from above/);
  await sleep(p, 5000);

  // The field notes are the screen AFTER the photo slots, not the slots
  // themselves. Shooting before this tap files the capture screen as
  // `05-field-notes.png`, which is what the first run of this script did
  // and what makes the two nearly the same height.
  await tap(p, /Next — what did you see|What did you see/);
  await sleep(p, 4000);
  await shot(p, '05-field-notes.png');

  // ---- identification --------------------------------------------------
  await tap(p, /^(Identify|Tell me|Done|Skip|Next)/);
  await sleep(p, 9000);
  await shot(p, '07-result.png');

  // ---- and after answering one of its questions ------------------------
  await tap(p, /rule things out/).catch(() => {});
  await sleep(p, 2500);
  const answered = await tap(p, /^(White|Yellow|Brown|Cream|Running down|Free,|Squarely|Notched|Smooth|Fibrous)/)
    .catch(() => null);
  await sleep(p, 7000);
  await shot(p, '08-result-after-answering.png');
  console.log(`  (answered: ${answered || 'no option offered'})`);

  // ---- the log ---------------------------------------------------------
  // The result sits above the tab navigator too, so there is no tab bar to
  // leave by. Same reload as after the emergency screen -- and the log is
  // in localStorage, so the observation just made is still there.
  await p.goto(URL, { waitUntil: 'domcontentloaded', timeout: 120000 });
  await sleep(p, 12000);
  await goTab(p, 'Me');
  await sleep(p, 3500);
  await shot(p, '09-history.png');

  // ---- the spore print flow --------------------------------------------
  // Reached from a log entry, not from the capture screen. The other route
  // is the result screen's "Walk me through it", which appears only while
  // the next question happens to be `spore_print_colour` -- so it depends
  // on what the classifier returned, which is the stub, which is nonsense.
  // The log route is deterministic and is also the real one: a print takes
  // two to twelve hours, so it is almost always started from a record
  // rather than in the moment.
  await tap(p, /Not recognised|Most likely|I'm not sure|can't safely/);
  await sleep(p, 2500);
  await tap(p, /Take a spore print/);
  await sleep(p, 4000);
  await shot(p, 'sp-03-spore-print-guide.png');

  console.log(`\n  page errors: ${errs.length ? errs.join(' | ') : 'none'}\n`);
  await browser.close();
})();
